#!/usr/bin/env python3
from pwn import *

r = remote('crypto.chal.csaw.io', 8000)
data = r.recvall().decode('utf-8').split('\n')

for line in data:
    if line.startswith('A:') or line.startswith('B:') or line.startswith('u:') or line.startswith('c:'):
        print(f"{line[:2]} (serialized matrix)")
